from AlgorithmImports import *
from datetime import timedelta, time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NEW_YORK)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).Symbol

        self.option_symbol = self.AddOption("SPY", Resolution.MINUTE).Symbol
        self.Securities[self.option_symbol].SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(timedelta(0), timedelta(365))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.minute_closes = {}
        self.entry_ticket = None
        self.entry_order_open = False
        self.held_contract = None
        self.entry_fill_price = None
        self.exit_ticket = None
        self.no_entries_date = None
        self.assignment_order_open = False

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_day()

        if self.held_contract is not None:
            self._evaluate_exit(data)

        if self.spy not in data.Bars:
            return

        spy_bar = data.Bars[self.spy]
        self._update_five_minute_consolidation(spy_bar, data)

    def _update_five_minute_consolidation(self, bar: TradeBar, data: Slice):
        end = bar.EndTime

        if end.time() < time(9, 31) or end.time() > time(16, 0):
            return

        self.minute_closes[end] = bar.Close

        # A five-minute bar closes on New York clock boundaries: 09:35, 09:40, etc.
        if end.minute % 5 != 0:
            return

        if end.time() < time(9, 35):
            return

        expected_times = [end - timedelta(minutes=i) for i in range(4, -1, -1)]
        if all(expected in self.minute_closes for expected in expected_times):
            close = self.minute_closes[end]
            self._on_completed_five_minute_bar(end, close, data)

        # Retain only a small amount of data; missing intervals are never filled.
        cutoff = end - timedelta(minutes=10)
        self.minute_closes = {
            timestamp: value
            for timestamp, value in self.minute_closes.items()
            if timestamp >= cutoff
        }

    def _on_completed_five_minute_bar(self, end_time, close, data: Slice):
        self.fast.Update(end_time, close)
        self.slow.Update(end_time, close)

        bullish_cross = (
            self.fast.IsReady
            and self.slow.IsReady
            and self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        if not bullish_cross:
            return

        if not (time(9, 45) <= end_time.time() <= time(14, 30)):
            return

        self._try_enter(data, close)

    def _try_enter(self, data: Slice, spy_price: float):
        if self.no_entries_date == self.Time.date():
            return

        if self.held_contract is not None or self.entry_order_open:
            return

        if self.option_symbol not in data.OptionChains:
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        contracts = list(data.OptionChains[self.option_symbol])
        minimum_expiry = self.Time.date() + timedelta(days=7)

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug("Entry skipped: no expiration at least 7 calendar days away.")
            return

        expiry = eligible_expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == expiry
            and contract.Right == OptionRight.CALL
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call at selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_open = True
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {expiry}, "
            f"strike {selected.Strike}."
        )

    def _evaluate_exit(self, data: Slice):
        if self.held_contract is None:
            return

        if self._is_pre_expiration_time_stop():
            self._submit_exit("pre-expiration time stop")
            return

        if self.held_contract not in data.QuoteBars:
            return

        quote = data.QuoteBars[self.held_contract]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self._submit_exit("50% profit target")

    def _is_pre_expiration_time_stop(self):
        if self.Time.hour != 15 or self.Time.minute != 45:
            return False

        expiry = self.held_contract.ID.Date.date()
        previous_trading_day = expiry - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(previous_trading_day):
            previous_trading_day -= timedelta(days=1)

        return self.Time.date() == previous_trading_day

    def _handle_expiration_day(self):
        if self.held_contract is None:
            return

        if self.Time.date() == self.held_contract.ID.Date.date():
            self.no_entries_date = self.Time.date()
            self._submit_exit("expiration-day protection")

    def _submit_exit(self, reason: str):
        if self.held_contract is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status not in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID
        ):
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
        self.Debug(f"Exit submitted ({reason}): {self.held_contract}.")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self.assignment_order_open:
            return

        self.assignment_order_open = True
        self.Debug(
            f"Unexpected SPY exercise/assignment position detected ({quantity}); "
            "liquidating."
        )
        self.MarketOrder(self.spy, -quantity)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.FILLED:
                self.entry_order_open = False
                self.held_contract = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_fill_price:.2f}."
                )
            elif order_event.Status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.entry_order_open = False
                self.entry_ticket = None
                self.Debug("Entry order did not fill.")

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.FILLED:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}.")
                self.held_contract = None
                self.entry_fill_price = None
                self.exit_ticket = None

