from AlgorithmImports import *
from datetime import datetime, timedelta


class FiveMinuteSpyCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(lambda universe: universe.IncludeWeeklys().Strikes(-200, 200).Expiration(0, 365))

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self._bucket_end = None
        self._bucket_closes = []
        self._bucket_last_end = None

        self.held_contract = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.expiry_date = None
        self.no_entry_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self._time_stop
        )

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration(data)

        if self.held_contract is not None:
            self._check_profit_target(data)

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is not None:
            self._update_five_minute_bar(spy_bar, data)

    def _update_five_minute_bar(self, minute_bar: TradeBar, data: Slice):
        end = minute_bar.EndTime
        if end.hour < 9 or (end.hour == 9 and end.minute < 31):
            return
        if end.hour > 16 or (end.hour == 16 and end.minute > 0):
            return

        minutes_after_midnight = end.hour * 60 + end.minute
        boundary_minutes = ((minutes_after_midnight + 4) // 5) * 5
        bucket_end = datetime(end.year, end.month, end.day) + timedelta(minutes=boundary_minutes)

        if bucket_end.hour < 9 or (bucket_end.hour == 9 and bucket_end.minute < 35):
            return
        if bucket_end.hour > 16 or (bucket_end.hour == 16 and bucket_end.minute > 0):
            return

        if self._bucket_end != bucket_end:
            self._bucket_end = bucket_end
            self._bucket_closes = []
            self._bucket_last_end = None

        expected_first_end = bucket_end - timedelta(minutes=4)
        is_next_minute = (
            self._bucket_last_end is None and end == expected_first_end
        ) or (
            self._bucket_last_end is not None and end == self._bucket_last_end + timedelta(minutes=1)
        )

        if not is_next_minute:
            self._bucket_closes = []

        self._bucket_closes.append(minute_bar.Close)
        self._bucket_last_end = end

        if end != bucket_end:
            return

        if len(self._bucket_closes) != 5:
            self._bucket_closes = []
            return

        close = self._bucket_closes[-1]
        self._bucket_closes = []

        prior_fast = self.fast.Current.Value if self.fast.IsReady else None
        prior_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bucket_end, close)
        self.slow.Update(bucket_end, close)

        if prior_fast is not None and prior_slow is not None and self.fast.IsReady and self.slow.IsReady:
            bullish = prior_fast <= prior_slow and self.fast.Current.Value > self.slow.Current.Value
            if bullish:
                self._try_enter(data, bucket_end, close)

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

    def _try_enter(self, data: Slice, bar_end: datetime, spy_price: float):
        if not (bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45)):
            return
        if not (bar_end.hour < 14 or (bar_end.hour == 14 and bar_end.minute <= 30)):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.held_contract is not None or self.entry_order_id is not None:
            return

        if self.exit_order_id is not None:
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped: no SPY option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call and contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug(f"{self.Time}: Entry skipped: no call expiration at least 7 calendar days away.")
            return

        expiry = expiries[0]
        minimum_strike = spy_price * 1.01
        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{self.Time}: Entry skipped: no eligible call at selected expiration.")
            return

        contract = min(candidates, key=lambda x: (x.Strike, str(x.Symbol)))
        ticket = self.MarketOrder(contract.Symbol, 1)

        if ticket is not None:
            self.entry_order_id = ticket.OrderId
            self.Debug(
                f"{self.Time}: Entering 1 SPY call {contract.Symbol}, "
                f"expiry {expiry}, strike {contract.Strike}."
            )

    def _check_profit_target(self, data: Slice):
        if self.entry_price is None or self.exit_order_id is not None:
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next((x for x in chain if x.Symbol == self.held_contract), None)
        if contract is None or contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self._submit_exit("profit target")

    def _time_stop(self):
        if self.held_contract is None or self.exit_order_id is not None or self.expiry_date is None:
            return

        previous_trading_day = self.expiry_date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(previous_trading_day):
            previous_trading_day -= timedelta(days=1)

        if self.Time.date() == previous_trading_day:
            self._submit_exit("pre-expiration time stop")

    def _handle_expiration(self, data: Slice):
        if self.held_contract is None or self.expiry_date is None:
            return

        if self.Time.date() >= self.expiry_date:
            self.no_entry_date = self.Time.date()
            if self.exit_order_id is None:
                self.Debug(f"{self.Time}: Expiration processing: liquidating {self.held_contract}.")
                self._submit_exit("expiration safeguard")

    def _submit_exit(self, reason: str):
        if self.held_contract is None:
            return

        if self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if order.Id != self.entry_order_id:
                self.Transactions.CancelOrder(order.Id)

        ticket = self.MarketOrder(self.held_contract, -quantity)
        if ticket is not None:
            self.exit_order_id = ticket.OrderId
            self.Debug(f"{self.Time}: Exiting {self.held_contract}: {reason}.")

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Invested:
            quantity = self.Portfolio[self.spy].Quantity
            self.MarketOrder(self.spy, -quantity)
            self.Debug(f"{self.Time}: Unexpected SPY exercise/assignment position liquidated.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        if order_event.OrderId == self.entry_order_id:
            self.held_contract = order_event.Symbol
            self.entry_price = order_event.FillPrice
            self.expiry_date = order_event.Symbol.ID.Date.date()
            self.entry_order_id = None
            self.Debug(f"{self.Time}: Entry filled {self.held_contract} at {self.entry_price}.")
            return

        if order_event.OrderId == self.exit_order_id:
            self.Debug(f"{self.Time}: Exit filled {order_event.Symbol} at {order_event.FillPrice}.")
            self.held_contract = None
            self.entry_price = None
            self.expiry_date = None
            self.exit_order_id = None

