            self.Debug(f"Skipped entry at {self.Time}: expiration safety lockout.")
            return

        if self.entry_order_id is not None:
            self.Debug(f"Skipped entry at {self.Time}: entry order already open.")
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            self.Debug(f"Skipped entry at {self.Time}: option position already held.")
            return

        if self.option_symbol not in data.OptionChains:
            self.Debug(f"Skipped entry at {self.Time}: no SPY option chain in Slice.")
            return

        if self.spy not in data.Bars:
            self.Debug(f"Skipped entry at {self.Time}: no current SPY TradeBar.")
            return

        spy_price = data.Bars[self.spy].Close
        if spy_price <= 0:
            self.Debug(f"Skipped entry at {self.Time}: invalid SPY price.")
            return

        chain = data.OptionChains[self.option_symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

