            self.Debug(
                f"Expiration safety exit for {self.held_contract} at {self.Time}."
            )
            self.SubmitExit("expiration safety", replace_existing=True)

    def ScheduleTimeStop(self, contract):
        expiry_date = contract.ID.Date.date()
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        previous_open = exchange_hours.GetPreviousMarketOpen(
            datetime.combine(expiry_date, time.min), False
        )
        stop_date = previous_open.date()

