        )

    def TimeStop(self, contract):
        if contract != self.held_contract or not self.Portfolio[contract].Invested:
            return

        self.Debug(f"Time-stop exit for {contract} at {self.Time}.")
        self.SubmitExit("pre-expiration time stop")

    def SubmitExit(self, reason, replace_existing=False):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        if self.exit_order_id is not None:
            if not replace_existing:
                return

            old_ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
            if old_ticket is not None:
                old_ticket.Cancel("Replacing exit order")

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_contract}.")

    def HandleUnexpectedSpyPosition(self):
