from AlgorithmImports import *


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(-100, 100, timedelta(days=0), timedelta(days=365))
        self.option_symbol = self.option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._five_minute_start = None
        self._five_minute_bars = {}

        self._held_contract = None
        self._entry_price = None
        self._entry_order_id = None
        self._exit_order_id = None
        self._spy_cleanup_order_id = None
        self._do_not_enter_on = None

    def OnData(self, data: Slice):
        if self.Portfolio[self.spy].Quantity != 0:
            self._handle_unexpected_spy_position()
            return

        self._clear_completed_order_ids()

        if self._held_contract is not None:
            if self.Portfolio[self._held_contract].Quantity == 0 and not self._is_order_open(self._exit_order_id):
                self._held_contract = None
                self._entry_price = None
                self._exit_order_id = None

        if self._held_contract is not None:
            expiry_date = self._expiry_date(self._held_contract)
            if self.Time.date() >= expiry_date:
                self._do_not_enter_on = self.Time.date()
                self._submit_exit("expiration processing")
                return

            if self.Time.date() == self._previous_trading_day(expiry_date):
                if self.Time.hour == 15 and self.Time.minute == 45:
                    self._submit_exit("expiration-eve time stop")

            self._check_profit_target(data)

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is None:
            return

        self._process_spy_minute_bar(spy_bar, data)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self._entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self._entry_price = order_event.FillPrice
                self._held_contract = order_event.Symbol
                self._entry_order_id = None
                self.Debug(
                    f"Entered {order_event.Symbol}: 1 call filled at {order_event.FillPrice:.2f}"
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry order for {order_event.Symbol} did not fill: {order_event.Status}")
                self._entry_order_id = None

        if order_event.OrderId == self._exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exited {order_event.Symbol}: {order_event.FillQuantity} at "
                    f"{order_event.FillPrice:.2f}"
                )
                self._held_contract = None
                self._entry_price = None
                self._exit_order_id = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self._exit_order_id = None

        if order_event.OrderId == self._spy_cleanup_order_id:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self._spy_cleanup_order_id = None

    def _process_spy_minute_bar(self, bar: TradeBar, data: Slice):
        minute_start = bar.EndTime - timedelta(minutes=1)

        if (minute_start.hour < 9 or
                (minute_start.hour == 9 and minute_start.minute < 30) or
                minute_start.hour >= 16):
            return

        bucket_start = minute_start.replace(
            minute=(minute_start.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self._five_minute_start != bucket_start:
            self._five_minute_start = bucket_start
            self._five_minute_bars = {}

        self._five_minute_bars[bar.EndTime] = bar
        bucket_end = bucket_start + timedelta(minutes=5)

        if bar.EndTime != bucket_end:
            return

        expected_end_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if all(end_time in self._five_minute_bars for end_time in expected_end_times):
            self._on_completed_five_minute_bar(bar.EndTime, bar.Close, data)

        self._five_minute_start = None
        self._five_minute_bars = {}

    def _on_completed_five_minute_bar(self, end_time, close, data: Slice):
        previous_fast_ready = self.fast.IsReady
        previous_slow_ready = self.slow.IsReady
        previous_fast = self.fast.Current.Value
        previous_slow = self.slow.Current.Value

        point = IndicatorDataPoint(end_time, close)
        self.fast.Update(point)
        self.slow.Update(point)

        bullish_cross = (
            previous_fast_ready and
            previous_slow_ready and
            self.fast.IsReady and
            self.slow.IsReady and
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        if not bullish_cross:
            return

        if not (
            (end_time.hour == 9 and end_time.minute >= 45) or
            10 <= end_time.hour <= 13 or
            (end_time.hour == 14 and end_time.minute <= 30)
        ):
            return

        self._try_enter(data, close)

    def _try_enter(self, data: Slice, spy_price: float):
        if self._do_not_enter_on == self.Time.date():
            return

        if self._held_contract is not None:
            return

        if self._is_order_open(self._entry_order_id):
            return

        if spy_price <= 0:
            self.Debug("Skipped entry: SPY price was not positive.")
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no SPY option chain in the current Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call and
            self._expiry_date(contract.Symbol) >= minimum_expiry
        ]

        if not calls:
            self.Debug("Skipped entry: no call expiration at least seven calendar days away.")
            return

        selected_expiry = min(self._expiry_date(contract.Symbol) for contract in calls)
        required_strike = spy_price * 1.01

        candidates = [
            contract for contract in calls
            if self._expiry_date(contract.Symbol) == selected_expiry and
            contract.Strike >= required_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped entry: no eligible call at {selected_expiry} "
                f"with strike >= {required_strike:.2f}."
            )
            return

        selected = min(candidates, key=lambda contract: (contract.Strike, str(contract.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1, tag="5-minute bullish crossover entry")
        self._entry_order_id = ticket.OrderId
        self.Debug(
            f"Submitted entry for {selected.Symbol}; strike {selected.Strike:.2f}, "
            f"expiry {selected_expiry}."
        )

    def _check_profit_target(self, data: Slice):
        if self._held_contract is None or self._entry_price is None:
            return

        if self._is_order_open(self._exit_order_id):
            return

        quote = data.QuoteBars.get(self._held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self._entry_price * 1.50:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self._held_contract is None or self._is_order_open(self._exit_order_id):
            return

        quantity = self.Portfolio[self._held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self._held_contract):
            self.Transactions.CancelOrder(order.Id, "Canceling other exit order")

        ticket = self.MarketOrder(
            self._held_contract,
            -quantity,
            tag=reason
        )
        self._exit_order_id = ticket.OrderId
        self.Debug(f"Submitted exit for {self._held_contract}: {reason}.")

    def _handle_unexpected_spy_position(self):
        if self._is_order_open(self._spy_cleanup_order_id):
            return

        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.Debug(
            f"Unexpected SPY equity position ({quantity}) from exercise or assignment; liquidating."
        )
        ticket = self.MarketOrder(self.spy, -quantity, tag="Unexpected exercise/assignment cleanup")
        self._spy_cleanup_order_id = ticket.OrderId

    def _previous_trading_day(self, expiry_date):
        expiry = datetime.combine(expiry_date, datetime.min.time())
        previous = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(expiry)
        return previous.date()

    def _expiry_date(self, symbol):
        return symbol.ID.Date.date()

    def _is_order_open(self, order_id):
        if order_id is None:
            return False

        order = self.Transactions.GetOrderById(order_id)
        return order is not None and order.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def _clear_completed_order_ids(self):
        if self._entry_order_id is not None and not self._is_order_open(self._entry_order_id):
            order = self.Transactions.GetOrderById(self._entry_order_id)
            if order is not None and order.Status != OrderStatus.Filled:
                self._entry_order_id = None

        if self._exit_order_id is not None and not self._is_order_open(self._exit_order_id):
            order = self.Transactions.GetOrderById(self._exit_order_id)
            if order is not None and order.Status != OrderStatus.Filled:
                self._exit_order_id = None
